                    const { Data: { TimeFrom: batchFromTs, Data: batch } } = await _fetch(`${API_URL_CRYPTOCOMPARE}/v2/histohour`
                        + `?fsym=${cryptoCurrency}&tsym=${vsCurrency}&toTs=${batchToTs}&limit=2000`, exports.Provider.CryptoCompare);
